export function normalizeReclubCode(value) {
  const code = String(value || '').trim().toUpperCase();
  if (!/^[A-Z0-9]{6}$/.test(code)) throw new Error('Enter a six-character Reclub meet code.');
  return code;
}
export function freezeReclub(value) {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    Object.values(value).forEach(freezeReclub);
    Object.freeze(value);
  }
  return value;
}
