// Optional Reclub identity on explicitly imported players; no legacy backfill.
const GUEST_REF = /^dm-reclub-guest:[A-Z0-9]{6}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const accountId = value => Number.isSafeInteger(value) && value > 0;

export function reclubImportIdentity(row = {}) {
  const external = row.referenceType === 2 && row.referenceId === null;
  const referenceId = external ? row.guestReference : row.referenceId ?? null;
  const guest = row.isGuest === true || row.referenceType === 3 || external;
  if (guest && row.referenceType === 2 && (typeof referenceId !== 'string' || !GUEST_REF.test(referenceId))) throw new Error('Invalid guest reference');
  if (guest && row.referenceType === 3 && !accountId(referenceId)) throw new Error('Invalid inviter reference');
  if (guest && ![2, 3].includes(row.referenceType)) throw new Error('Unknown guest shape');
  if (guest) return { referenceId, referenceType: row.referenceType ?? 3, isGuest: true, reclubUserId: null, reclubHandle: null };
  const knownAccount = row.isGuest === false || Number.isInteger(row.referenceType);
  const id = row.reclubUserId ?? referenceId;
  if (knownAccount && !accountId(id)) throw new Error('Invalid account reference');
  return { referenceId, referenceType: row.referenceType ?? null, isGuest: knownAccount ? false : null,
    reclubUserId: knownAccount ? id : null,
    reclubHandle: knownAccount && typeof row.reclubHandle === 'string' ? row.reclubHandle.trim() || null : null };
}

export function reclubIdLabel(row) {
  return row.isGuest === true ? 'Guest' : accountId(row.reclubUserId) ? String(row.reclubUserId) : '';
}

export function validReclubImport(payload) {
  const rows = payload?.participants;
  if (!Array.isArray(rows) || rows.length === 0) return false;
  if (payload.confirmedCount !== undefined && (!Number.isInteger(payload.confirmedCount) || payload.confirmedCount !== rows.length)) return false;
  const guests = new Set();
  try {
    for (const row of rows) {
      if (!row || typeof row.name !== 'string' || !row.name.trim() || (row.status !== undefined && row.status !== 1)) return false;
      const identity = reclubImportIdentity(row);
      if (identity.isGuest && identity.referenceType === 2) {
        if (guests.has(identity.referenceId)) return false;
        if (payload.referenceCode && !identity.referenceId.startsWith(`dm-reclub-guest:${String(payload.referenceCode).toUpperCase()}:`)) return false;
        guests.add(identity.referenceId);
      }
    }
    return true;
  } catch { return false; }
}
