import { freezeReclub, normalizeReclubCode } from "./reclubResult";
import config from "../config";
import BaseService from "./BaseService";
import reclubDefaults from "../config/reclub";

const isRecord = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const isId = (value) => Number.isSafeInteger(value) && value > 0;

// A successful HTTP response must still describe a complete roster before the
// modal can offer replacement of the current session.
function isMeetPayload(data, code) {
  if (!isRecord(data) || !isRecord(data.meet)
    || data.meet.referenceCode !== code.toUpperCase()
    || !Array.isArray(data.meet.participants) || !Array.isArray(data.players)) return false;
  const declaredCount = data.meet.confirmedCount;
  if (declaredCount !== undefined && (!Number.isInteger(declaredCount) || declaredCount < 0
    || declaredCount !== data.meet.participants.filter(p => p?.status === 1).length)) return false;
  const profiles = new Map();
  for (const player of data.players) {
    if (!isRecord(player) || !isId(player.userId) || typeof player.name !== "string"
      || profiles.has(player.userId)) return false;
    profiles.set(player.userId, player);
  }
  const guestReferences = new Set();
  return data.meet.participants.every((participant) => {
    const externalGuest = isRecord(participant) && participant.referenceType === 2 && participant.referenceId === null;
    if (externalGuest) {
      if (declaredCount === undefined) return false;
      const ref = participant.guestReference;
      if (typeof ref !== 'string' || !ref.startsWith(`dm-reclub-guest:${code.toUpperCase()}:`)
        || !/^dm-reclub-guest:[A-Z0-9]{6}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(ref)
        || guestReferences.has(ref)) return false;
      guestReferences.add(ref);
    }
    if (!isRecord(participant) || !Number.isInteger(participant.status)
      || typeof participant.isHost !== "boolean" || (!isId(participant.referenceId) && !externalGuest)
      || !Number.isInteger(participant.referenceType)) return false;
    if (participant.status !== 1) return true;
    const name = participant.referenceType === 3 || externalGuest
      ? participant.externalReference?.name
      : profiles.get(participant.referenceId)?.name;
    return typeof name === "string" && name.trim().length > 0;
  });
}

/**
 * ReclubService
 * Placeholder integration for Reclub APIs.
 * Configure endpoints, org/location, and API key in client config.
 */
export class ReclubService extends BaseService {
  constructor() {
    const cfg = config.reclub || {};
    const base = cfg.apiBaseUrl || reclubDefaults.apiBaseUrl;
    super(base, {});
  }

  /**
   * Fetch players for a given day.
   * date: ISO string (YYYY-MM-DD) or Date instance.
   * You likely need to pass orgId/locationId in query; wired from config.
   */
  async getPlayersForDate(date) {
    const d = date instanceof Date
      ? date.toISOString().slice(0, 10)
      : String(date || "");
    const { orgId, locationId } = config.reclub || {};
    // TODO: Adjust endpoint/params to match real Reclub API
    return this.request("/players", {
      query: { date: d, orgId, locationId },
    });
  }

  /**
   * Fetch single player details by ID.
   */
  async getPlayerDetails(playerId) {
    // TODO: Adjust endpoint to match real Reclub API
    return this.request(`/players/${encodeURIComponent(playerId)}`);
  }

  /**
   * Fetch multiple players by user IDs (comma-separated or array)
   * Example endpoint: /players/userIds?scopes=BASIC_PROFILE&user_ids=1,2,3
   */
  async getPlayersByUserIds(userIds, result) {
    if (!userIds || (Array.isArray(userIds) && userIds.length === 0)) {
      return { players: [] };
    }
    const rawIds = Array.isArray(userIds) ? userIds : String(userIds).split(",");
    const wanted = new Set(rawIds.map((id) => String(id).trim()).filter((id) => id !== ""));
    const cached = Array.isArray(result?.players) ? result.players : [];
    const players = cached
      .filter((player) => wanted.has(String(player?.userId)))
      .map((player) => {
        const row = {
          userId: player.userId,
          name: player.name,
          gender: player.gender,
          imageUrl: player.imageUrl,
        };
        if (player.username != null) row.username = player.username;
        return row;
      });
    return { players };
  }

  /**
   * Fetch meet details by its reference code (e.g., GB7NMN).
   * The meet page is read by our server. This does not call api.reclub.co.
   */
  async getMeetByRef(ref) { return (await this.getMeetResult(ref)).meet; }

  async getMeetResult(ref) {
    const code = normalizeReclubCode(ref);

    const base = String(process.env.REACT_APP_API_URL || "").replace(/\/$/, "");
    const res = await fetch(`${base}/api/reclub/meet/${encodeURIComponent(code)}`, {
      method: "GET",
      headers: { Accept: "application/json" },
    });
    const text = await res.text();
    let data = null;
    if (text) {
      try {
        data = JSON.parse(text);
      } catch {
        data = text;
      }
    }
    if (!res.ok) {
      const message = data && typeof data === "object" && typeof data.message === "string"
        ? data.message
        : `HTTP ${res.status}`;
      const err = new Error(message);
      err.status = res.status;
      err.data = data;
      throw err;
    }
    if (!isMeetPayload(data, code)) {
      const err = new Error("Reclub changed the page. Import was not run.");
      err.data = data;
      throw err;
    }
    return freezeReclub(data);
  }
}

// Export a ready-to-use singleton instance.
const reclubService = new ReclubService();
export default reclubService;
